def split(g):
    h, w = len(g), len(g[0])
    def cnt(v): return sum(r.count(v) for r in g)
    for i in range(h):
        if len(set(g[i])) == 1 and cnt(g[i][0]) == w:
            return [r[:i] for r in g], [r[i+1:] for r in g]
    for j in range(w):
        col = [r[j] for r in g]
        if len(set(col)) == 1 and cnt(col[0]) == h:
            return [r[:j] for r in g], [r[j+1:] for r in g]
    raise ValueError('no separator line')

